std::uint32_t left(Family f){switch(f){case Family::Vassal:return 0x128;case Family::Marriage:return 0x68;case Family::Improve:return 0x1d0;case Family::Guarantee:return 0x1a0;case Family::Curry:return 0x158;default:throw false;}}
std::uint32_t right(Family f){return f==Family::Improve?0x1e8:left(f);}
std::uint64_t relation_vt(Family f){switch(f){case Family::Vassal:return 0x1c81758;case Family::Marriage:return 0x1c80be0;case Family::Improve:return 0x1c81658;case Family::Guarantee:return 0x1c817d8;case Family::Curry:return 0x1c7b178;default:throw false;}}
void zero(Memory& m,std::uint64_t a,std::size_t n){for(std::size_t i=0;i<n;++i)m.put(a+i,std::uint8_t{0});}
void typed(Memory& m,std::uint64_t a,std::uint64_t vt,std::uint32_t marker=0x165){m.put(a,module+vt);m.put(a+8,marker);}
void engine_string(Memory& m,std::uint64_t def,std::string_view text,bool heap=false){
 auto b=def+0x10;const auto chars=heap?def+0x100:b;zero(m,chars,text.size()+1);for(std::size_t i=0;i<text.size();++i)m.put(chars+i,static_cast<std::uint8_t>(text[i]));
 if(heap)m.put(b,chars);m.put(b+0x10,static_cast<std::uint64_t>(text.size()));m.put(b+0x18,std::uint64_t{heap?31U:15U});
}
void index_row(Memory& m,std::uint64_t rootValue,std::uint32_t offset,std::uint64_t array,std::uint32_t slot,std::uint64_t object){
 m.put(rootValue+offset,array);m.put(rootValue+offset+8,std::int32_t{1});m.put(rootValue+offset+12,std::int32_t{1});zero(m,array,16);m.put(array,slot);m.put(array+8,object);
}
