bool sample(Memory& m,Family f,cancel1375::Snapshot& out,const PairStamp& s=::stamp()){return cancel1375::two_pass(m,module,f,s,out);}
bool read_at(const Memory& m,std::uint64_t at){return std::find(m.addresses.begin(),m.addresses.end(),at)!=m.addresses.end();}
struct ReadGuard final:SyntheticGuard {
 Guard& base;Memory& memory;ReadGuard(Guard& b,Memory& m):base(b),memory(m){}
 std::uint64_t clock()override{return base.clock();}bool stamp(const Request& q,PairStamp& s)override{return base.stamp(q,s);}
 bool cancellation(Family f,const PairStamp& s,CancelObservation& o)override{cancel1375::Snapshot snap;if(!sample(memory,f,snap,s))return false;o=snap.selected;return true;}
};
